        s.elementStreak=same?s.elementStreak+1:0;s.lastElement=el;s.elements[el]=G.t+8;
        if(s.a===3)frame.elementMul=Math.min(.3,Object.values(s.elements).filter(t=>t>G.t).length*.1);
        s.elementMul=frame.elementMul;
